package org.apache.commons.math4.legacy.stat.descriptive;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import org.apache.commons.math4.legacy.stat.descriptive.StatisticalSummary;
import org.apache.commons.math4.legacy.stat.descriptive.Statistics;
import org.apache.commons.math4.legacy.stat.descriptive.StorelessUnivariateStatistic;
import org.apache.commons.math4.legacy.stat.descriptive.SummaryStatistics;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class) @EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class SummaryStatistics_ESTest extends SummaryStatistics_ESTest_scaffolding {

  private static final double DELTA = 0.01;

  /**
   * A statistic implementation cannot be swapped in once values have already
   * been added; doing so must raise a RuntimeException.
   */
  @Test(timeout = 4000)
  public void setVarianceImplAfterAddingValueThrows() throws Throwable {
      SummaryStatistics stats = new SummaryStatistics();
      Statistics.StorelessMax maxStatistic = Statistics.StorelessMax.create();
      stats.addValue(0.0);

      try {
        stats.setVarianceImpl(maxStatistic);
        fail("Expecting exception: RuntimeException");
      } catch (RuntimeException e) {
         // 1 values have been added before statistic is configured
         verifyException("org.apache.commons.math4.legacy.stat.descriptive.SummaryStatistics", e);
      }
  }

  /** Clearing a fresh instance leaves the count at zero. */
  @Test(timeout = 4000)
  public void clearResetsCountToZero() throws Throwable {
      SummaryStatistics stats = new SummaryStatistics();
      stats.clear();
      assertEquals(0L, stats.getN());
  }

  /** Configuring custom implementations and then clearing still yields a zero count. */
  @Test(timeout = 4000)
  public void clearAfterConfiguringCustomImplsResetsCount() throws Throwable {
      SummaryStatistics stats = new SummaryStatistics();
      Statistics.StorelessGeometricMean geometricMean = Statistics.StorelessGeometricMean.create();
      stats.setSumImpl(geometricMean);
      stats.setMaxImpl(geometricMean);
      stats.setVarianceImpl(geometricMean);
      stats.setMinImpl(geometricMean);
      stats.setMeanImpl(geometricMean);

      stats.clear();

      assertEquals(0L, stats.getN());
  }

  /** Standard deviation is computed over the two added values. */
  @Test(timeout = 4000)
  public void getStandardDeviationOfTwoValues() throws Throwable {
      SummaryStatistics stats = new SummaryStatistics();
      stats.addValue(2536.6);
      stats.addValue(-4145.465349642632);

      double standardDeviation = stats.getStandardDeviation();

      assertEquals(2L, stats.getN());
      assertEquals(4724.933721063963, standardDeviation, DELTA);
  }

  /** toString works after adding a NaN value with a custom sum implementation. */
  @Test(timeout = 4000)
  public void toStringAfterAddingNaNWithCustomSumImpl() throws Throwable {
      SummaryStatistics stats = new SummaryStatistics();
      Statistics.StorelessSum sumStatistic = Statistics.StorelessSum.create();
      stats.setSumImpl(sumStatistic);
      stats.addValue(Double.NaN);

      stats.toString();

      assertEquals(1L, stats.getN());
  }

  /** No mean implementation is configured on a fresh instance. */
  @Test(timeout = 4000)
  public void getMeanImplIsNullByDefault() throws Throwable {
      SummaryStatistics stats = new SummaryStatistics();
      StorelessUnivariateStatistic meanImpl = stats.getMeanImpl();
      assertNull(meanImpl);
  }

  /** A copy constructed instance is not considered equal to its source. */
  @Test(timeout = 4000)
  public void copyConstructedInstanceIsNotEqualToSource() throws Throwable {
      SummaryStatistics original = new SummaryStatistics();
      SummaryStatistics copy = new SummaryStatistics(original);
      assertFalse(copy.equals((Object) original));
  }

  /** Copying an instance onto itself leaves its count unchanged. */
  @Test(timeout = 4000)
  public void copyOntoSelfKeepsCount() throws Throwable {
      SummaryStatistics stats = new SummaryStatistics();
      Statistics.StorelessGeometricMean geometricMean = Statistics.StorelessGeometricMean.create();
      stats.setSumImpl(geometricMean);
      stats.setMaxImpl(geometricMean);
      stats.setVarianceImpl(geometricMean);
      stats.setMinImpl(geometricMean);
      stats.setMeanImpl(geometricMean);

      SummaryStatistics.copy(stats, stats);

      assertEquals(0L, stats.getN());
  }

  /** copy() returns a distinct instance. */
  @Test(timeout = 4000)
  public void copyReturnsDistinctInstance() throws Throwable {
      SummaryStatistics original = new SummaryStatistics();
      SummaryStatistics copy = original.copy();
      assertNotSame(copy, original);
  }

  /** No max implementation is configured on a fresh instance. */
  @Test(timeout = 4000)
  public void getMaxImplIsNullByDefault() throws Throwable {
      SummaryStatistics stats = new SummaryStatistics();
      StorelessUnivariateStatistic maxImpl = stats.getMaxImpl();
      assertNull(maxImpl);
  }

  /** No min implementation is configured on a fresh instance. */
  @Test(timeout = 4000)
  public void getMinImplIsNullByDefault() throws Throwable {
      SummaryStatistics stats = new SummaryStatistics();
      StorelessUnivariateStatistic minImpl = stats.getMinImpl();
      assertNull(minImpl);
  }

  /** No sum implementation is configured on a fresh instance. */
  @Test(timeout = 4000)
  public void getSumImplIsNullByDefault() throws Throwable {
      SummaryStatistics stats = new SummaryStatistics();
      StorelessUnivariateStatistic sumImpl = stats.getSumImpl();
      assertNull(sumImpl);
  }

  /** toString of an empty instance reports NaN for every statistic. */
  @Test(timeout = 4000)
  public void toStringOfEmptyInstance() throws Throwable {
      SummaryStatistics stats = new SummaryStatistics();
      String summary = stats.toString();
      assertEquals("SummaryStatistics:\nn: 0\nmin: NaN\nmax: NaN\nsum: NaN\nmean: NaN\nvariance: NaN\nstandard deviation: NaN\n", summary);
  }

  /** The summary of an empty instance reports NaN for the sum. */
  @Test(timeout = 4000)
  public void getSummaryOfEmptyInstanceHasNaNSum() throws Throwable {
      SummaryStatistics stats = new SummaryStatistics();
      StatisticalSummary summary = stats.getSummary();
      assertEquals(Double.NaN, summary.getSum(), DELTA);
  }

  /** No variance implementation is configured on a fresh instance. */
  @Test(timeout = 4000)
  public void getVarianceImplIsNullByDefault() throws Throwable {
      SummaryStatistics stats = new SummaryStatistics();
      StorelessUnivariateStatistic varianceImpl = stats.getVarianceImpl();
      assertNull(varianceImpl);
  }
}
